INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('1','1','acne-hydrafacial','Acne Hydrafacial','259000','','45 menit','Membersihkan pori, mengangkat sebum berlebih, dan menenangkan kulit berjerawat dalam satu sesi.','assets/uploads/layanan/20261020-070747-5b729728.webp','0','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-facial.jpg','https://www.youtube.com/watch?v=T9BBwvPqYKI','Membersihkan, mengangkat, lalu menutrisi','Hydrafacial memakai teknologi vakum dan serum untuk membersihkan pori, mengangkat sel kulit mati, lalu menutrisi kulit — nyaman dan tanpa pemulihan panjang.','Membersihkan pori mendalam\nEksfoliasi yang lembut\nInfus serum sesuai kebutuhan kulit\nTanpa waktu pemulihan panjang','Kulit kusam atau tidak merata\nPori tampak besar atau mudah tersumbat\nIngin perawatan rutin yang nyaman\nKulit butuh hidrasi','Hindari paparan matahari berlebih setelah tindakan\nGunakan tabir surya setiap hari\nBeri tahu dokter bila sedang memakai obat topikal tertentu\nHasil dapat berbeda pada tiap orang','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('2','1','brightening-hydrafacial','Brightening Hydrafacial','259000','','45 menit','Pembersihan mendalam, eksfoliasi lembut, dan infus serum pencerah untuk kulit tampak segar dan bercahaya.','assets/images/treatment-facial.jpg','1','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-peel.jpg','assets/images/treatment-booster.jpg','Membersihkan, mengangkat, lalu menutrisi','Hydrafacial memakai teknologi vakum dan serum untuk membersihkan pori, mengangkat sel kulit mati, lalu menutrisi kulit — nyaman dan tanpa pemulihan panjang.','Membersihkan pori mendalam\nEksfoliasi yang lembut\nInfus serum sesuai kebutuhan kulit\nTanpa waktu pemulihan panjang','Kulit kusam atau tidak merata\nPori tampak besar atau mudah tersumbat\nIngin perawatan rutin yang nyaman\nKulit butuh hidrasi','Hindari paparan matahari berlebih setelah tindakan\nGunakan tabir surya setiap hari\nBeri tahu dokter bila sedang memakai obat topikal tertentu\nHasil dapat berbeda pada tiap orang','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('3','1','salmon-dna-hydrafacial','Salmon DNA Hydrafacial','429000','','50 menit','Hydrafacial yang dilengkapi serum Salmon DNA untuk membantu melembapkan dan menunjang regenerasi kulit.','assets/images/treatment-facial.jpg','2','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-booster.jpg','assets/images/treatment-peel.jpg','Membersihkan, mengangkat, lalu menutrisi','Hydrafacial memakai teknologi vakum dan serum untuk membersihkan pori, mengangkat sel kulit mati, lalu menutrisi kulit — nyaman dan tanpa pemulihan panjang.','Membersihkan pori mendalam\nEksfoliasi yang lembut\nInfus serum sesuai kebutuhan kulit\nTanpa waktu pemulihan panjang','Kulit kusam atau tidak merata\nPori tampak besar atau mudah tersumbat\nIngin perawatan rutin yang nyaman\nKulit butuh hidrasi','Hindari paparan matahari berlebih setelah tindakan\nGunakan tabir surya setiap hari\nBeri tahu dokter bila sedang memakai obat topikal tertentu\nHasil dapat berbeda pada tiap orang','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('4','2','brightening-peel','Brightening Peel','259000','','30 menit','Chemical peeling ringan untuk membantu mencerahkan kulit kusam dan meratakan warna kulit.','assets/images/treatment-peel.jpg','0','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-facial.jpg','assets/images/treatment-booster.jpg','Eksfoliasi terkontrol oleh dokter','Larutan peeling dioleskan secara terkontrol untuk mengangkat lapisan kulit mati sehingga kulit baru tampak lebih halus dan merata seiring waktu.','Membantu meratakan warna kulit\nMembantu mengurangi sumbatan pori\nKonsentrasi disesuaikan kondisi kulit\nDilakukan bertahap','Kulit kusam dan noda ringan\nKulit berminyak atau mudah berjerawat\nTekstur kulit kasar\nArea khusus seperti bibir atau mata','Kulit dapat terasa hangat atau sedikit mengelupas\nWajib memakai tabir surya\nHindari scrub dan produk keras beberapa hari\nTidak disarankan saat kulit sedang iritasi berat','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
