INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('18','5','hair-restoration-therapy','Hair Restoration Therapy','1899000','','45 menit','Terapi kulit kepala untuk membantu merawat folikel dan menunjang pertumbuhan rambut yang lebih sehat.','assets/images/treatment-booster.jpg','0','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-facial.jpg','assets/images/treatment-peel.jpg','Merawat kulit kepala dan folikel','Terapi dilakukan pada kulit kepala untuk membantu menutrisi folikel rambut. Dokter akan menilai penyebab kerontokan sebelum menentukan protokol yang sesuai.','Evaluasi kondisi kulit kepala\nProtokol disesuaikan penyebab\nDilakukan oleh tenaga medis\nDilakukan bertahap','Rambut rontok atau menipis\nKulit kepala kering atau berminyak berlebih\nIngin merawat kesehatan rambut\nTelah berkonsultasi dengan dokter','Hasil membutuhkan waktu dan beberapa sesi\nIkuti anjuran perawatan di rumah\nBeri tahu dokter riwayat penyakit & obat\nHasil dapat berbeda pada tiap orang','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('19','6','v-line-liposculpt','V-Line LipoSculpt','429000','','30 menit','Tindakan injeksi untuk membantu membentuk kontur wajah bagian bawah agar tampak lebih tirus.','assets/images/treatment-antiaging.jpg','0','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-booster.jpg','assets/images/treatment-facial.jpg','Pembentukan kontur sesuai evaluasi dokter','Tindakan diberikan pada area tertentu setelah dokter menilai kebutuhan dan kondisi Anda. Hasil bergantung pada kondisi tubuh serta pola hidup.','Area & dosis ditentukan dokter\nTindakan singkat\nTanpa operasi\nEvaluasi hasil berkala','Ingin membentuk kontur wajah atau tubuh\nArea lemak yang membandel\nTelah berkonsultasi dengan dokter\nMenjalani pola hidup sehat','Bukan pengganti diet dan olahraga\nDapat muncul bengkak atau memar ringan\nTidak disarankan saat hamil atau menyusui\nHasil dapat berbeda pada tiap orang','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
