INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('23','7','cauterisasi','Cauterisasi','179000','','15–30 menit','Tindakan pengangkatan lesi kulit jinak seperti tahi lalat kecil, kutil, atau skin tag. Harga bergantung jumlah dan ukuran lesi.','assets/images/treatment-laser.jpg','0','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-peel.jpg','assets/images/treatment-facial.jpg','Pengangkatan lesi jinak yang presisi','Dokter memakai alat cauter untuk mengangkat lesi kulit jinak setelah area dibius lokal. Prosesnya singkat, dan jumlah serta ukuran lesi menentukan biaya akhir.','Tindakan singkat\nDibius lokal\nPresisi pada lesi kecil\nDievaluasi dokter sebelum tindakan','Tahi lalat kecil atau kutil\nSkin tag\nLesi jinak yang mengganggu penampilan\nTelah diperiksa dokter','Area bekas tindakan perlu dijaga tetap bersih dan kering\nGunakan salep sesuai anjuran\nHindari mengelupas keropeng\nLesi yang mencurigakan perlu pemeriksaan lebih lanjut','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('24','7','botox-100-ui','Botox 100 UI','4899000','','30 menit','Injeksi botulinum toxin oleh dokter untuk membantu menghaluskan garis ekspresi pada area tertentu.','assets/images/treatment-antiaging.jpg','1','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-booster.jpg','assets/images/treatment-facial.jpg','Menghaluskan garis ekspresi','Botulinum toxin diinjeksikan oleh dokter pada otot tertentu untuk membantu menghaluskan garis ekspresi, dengan dosis dan titik yang disesuaikan.','Dilakukan oleh dokter\nDosis & titik sesuai kebutuhan\nTindakan singkat\nHasil tampak natural','Garis dahi atau kerutan di sekitar mata\nIngin tampilan lebih rileks\nTelah berkonsultasi dengan dokter\nUsia dewasa dengan kondisi sehat','Tidak disarankan saat hamil atau menyusui\nHindari memijat area suntikan beberapa jam\nEfek muncul bertahap dan tidak permanen\nInformasikan riwayat penyakit & alergi','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('25','7','mounjaro-2-5-mg','Mounjaro 2,5 mg','4589000','','Sesuai arahan dokter','Terapi dengan resep dokter yang diberikan hanya setelah konsultasi dan evaluasi kondisi kesehatan.','assets/images/treatment-antiaging.jpg','2','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-booster.jpg','assets/images/treatment-peel.jpg','Hanya setelah konsultasi dokter','Terapi ini merupakan obat dengan resep. Dokter akan mengevaluasi kondisi kesehatan, riwayat penyakit, dan tujuan Anda sebelum menentukan apakah dan dosis mana yang sesuai.','Evaluasi kesehatan oleh dokter\nDosis sesuai arahan dokter\nPemantauan berkala\nEdukasi pola hidup','Telah berkonsultasi dengan dokter\nMemenuhi indikasi medis\nBersedia menjalani pemantauan\nMemberi tahu riwayat penyakit lengkap','Tidak untuk semua orang\nTidak disarankan saat hamil atau menyusui\nEfek samping dapat terjadi dan akan dijelaskan dokter\nJangan memakai tanpa pengawasan dokter','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
