INSERT IGNORE INTO `layanan_items` (`id`,`category_id`,`slug`,`name`,`price`,`price_prefix`,`duration`,`description`,`img`,`sort_order`,`is_active`,`created_at`,`updated_at`,`img2`,`img3`,`how_title`,`how_text`,`features`,`suitable`,`notes`,`steps`) VALUES ('27','7','collagen-therapy','Collagen Therapy','7899000','','60 menit','Terapi kolagen untuk membantu menunjang kekenyalan dan kekencangan kulit.','assets/images/treatment-antiaging.jpg','4','1','2026-10-20 13:04:26','2026-10-20 14:31:12','assets/images/treatment-facial.jpg','assets/images/treatment-booster.jpg','Menutrisi kulit dari dalam','Bahan aktif dimasukkan ke lapisan kulit melalui injeksi atau microneedle untuk membantu hidrasi, elastisitas, dan regenerasi kulit secara bertahap.','Membantu hidrasi lebih dalam\nMenunjang elastisitas kulit\nDiberikan langsung oleh dokter\nHasil bertahap dan alami','Kulit kering, tipis, atau tampak lelah\nTekstur kulit kurang halus\nIngin kulit lebih kenyal dan sehat\nBekas jerawat dan pemulihan kulit','Dapat muncul kemerahan atau bengkak ringan sementara\nHindari makeup beberapa jam setelah tindakan\nHindari sauna dan olahraga berat 24 jam\nTidak disarankan saat hamil atau menyusui','Konsultasi | Dokter menilai kondisi kulit dan tujuan Anda.\nPersiapan | Kulit dibersihkan dan disiapkan sebelum tindakan.\nTindakan | Perawatan dilakukan sesuai protokol dokter.\nPerawatan Pasca | Pemberian arahan dan produk pendukung.\nEvaluasi | Pemantauan hasil dan rencana sesi berikutnya.');
